"""Income tax: ITR, TDS/TCS, notices, audits, PAN/TAN.

Section numbers are deliberately avoided: the Income-tax Act, 2025 replaced the
1961 Act from 1 April 2026 and renumbered sections and forms."""

PORTAL = [('Income tax portal login', 'PAN and password, or we help you reset it.'), ('Aadhaar linked mobile', 'For OTP-based e-verification.')]
ITR_BASE = [('PAN and Aadhaar', 'Linked with each other.'), ('Form 26AS and AIS', 'We download them from the portal.'), ('Bank account details', 'All accounts held, with one for refund.')] + PORTAL[:1]
ITR_STEPS = [('Share documents', 'Upload your documents or give us portal access.'),
             ('Compute', 'We match income with AIS and Form 26AS and compare the old and new regimes.'),
             ('Review', 'You see the computation and tax payable or refund before filing.'),
             ('File and verify', 'We file the return and help you e-verify it.')]
TDS_STEPS = [('Collect data', 'Deductee details, payments and challans for the quarter.'),
             ('Validate', 'We check PANs, rates and challan matching.'),
             ('File', 'The statement is prepared, validated and filed.'),
             ('Certificates', 'We download and share TDS certificates for deductees.')]
NOTICE_STEPS = [('Read the notice', 'We explain what it means and the deadline.'),
                ('Gather facts', 'We match it with your return, AIS and records.'),
                ('Respond', 'We draft and file the response online.'),
                ('Follow up', 'We track the outcome and handle hearings.')]

