    d=ITR_BASE + [('Capital gains statements', 'From brokers and mutual fund registrars.'), ('Property documents', 'Purchase and sale deeds, improvement costs.'), ('Reinvestment proof', 'For any exemption claimed.'), ('Foreign investment statements', 'If you hold foreign shares.')],
